import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { mix, uv, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  const animationHandles = [];
  const primitiveHandles = [];
  const ownedResources = [];
  const accent = '#ff2a38';
  const paper = '#e8ecf2';
  const ink = '#16161d';
  const surface = '#0b0b10';

  root.name = 'ornamental-divider';
  root.userData.handlers = {};

  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    uv().y
  );
  backdropMaterial.toneMapped = false;

  const backdrop = new THREE.Mesh(
    new THREE.PlaneGeometry(7, 6),
    backdropMaterial
  );
  backdrop.name = 'machined-stage-backdrop';
  backdrop.position.z = -2.5;
  root.add(backdrop);
  ownedResources.push(backdrop.geometry, backdrop.material);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: surface,
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const contactShadow = new THREE.Mesh(
    new THREE.CircleGeometry(1.25, 48),
    shadowMaterial
  );
  contactShadow.name = 'divider-contact-shadow';
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.scale.set(1.8, 0.34, 1);
  contactShadow.position.set(0, -0.18, -0.12);
  root.add(contactShadow);
  ownedResources.push(contactShadow.geometry, contactShadow.material);

  const metalMaterial = new MeshStandardNodeMaterial({
    color: paper,
    metalness: 0.48,
    roughness: 0.58
  });
  const redMaterial = new MeshStandardNodeMaterial({
    color: accent,
    metalness: 0.3,
    roughness: 0.42,
    emissive: accent,
    emissiveIntensity: 0.7
  });
  const edgeMaterial = new MeshStandardNodeMaterial({
    color: accent,
    metalness: 0.34,
    roughness: 0.5,
    emissive: accent,
    emissiveIntensity: 0.35,
    transparent: true,
    opacity: 0
  });

  const ornament = new THREE.Group();
  ornament.name = 'machined-rule-fallback';
  root.add(ornament);

  const ruleGeometry = new THREE.BoxGeometry(2.5, 0.035, 0.045);
  const leftRule = new THREE.Mesh(ruleGeometry, metalMaterial);
  const rightRule = new THREE.Mesh(ruleGeometry, metalMaterial);
  leftRule.position.x = -0.72;
  rightRule.position.x = 0.72;
  ornament.add(leftRule, rightRule);

  const edgeGeometry = new THREE.BoxGeometry(2.62, 0.018, 0.064);
  const accentEdge = new THREE.Mesh(edgeGeometry, edgeMaterial);
  accentEdge.position.z = 0.035;
  ornament.add(accentEdge);

  const jewelGeometry = new THREE.OctahedronGeometry(0.115, 1);
  const jewel = new THREE.Mesh(jewelGeometry, redMaterial);
  jewel.name = 'signal-red-center-jewel';
  ornament.add(jewel);

  const capGeometry = new THREE.CylinderGeometry(0.06, 0.06, 0.08, 16);
  const leftCap = new THREE.Mesh(capGeometry, metalMaterial);
  const rightCap = new THREE.Mesh(capGeometry, metalMaterial);
  leftCap.rotation.z = Math.PI / 2;
  rightCap.rotation.z = Math.PI / 2;
  leftCap.position.x = -1.98;
  rightCap.position.x = 1.98;
  ornament.add(leftCap, rightCap);

  ownedResources.push(
    ruleGeometry,
    edgeGeometry,
    jewelGeometry,
    capGeometry,
    metalMaterial,
    redMaterial,
    edgeMaterial
  );

  const key = new THREE.PointLight(paper, 0.95, 5);
  key.position.set(1.4, 1.2, 2.2);
  root.add(key);

  const rim = new THREE.PointLight(accent, 0.72, 4);
  rim.position.set(-1.2, 0.2, 1.5);
  root.add(rim);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (typeof item?.text !== 'string') continue;
    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize,
      color: item.role === 'accent' ? accent : paper,
      align: item.align ?? 'center',
      maxWidthPx: item.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });
    textObject.position.set(
      item.position?.x ?? 0,
      item.position?.y ?? -0.42,
      item.position?.z ?? 0.08
    );
    root.add(textObject);
  }

  const meshUrl = config.meshUrl;
  if (meshUrl) {
    ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
      if (gltf?.scene) {
        gltf.scene.name = 'loaded-machined-divider';
        root.add(gltf.scene);
      }
    }).catch(() => {});
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const primitiveFactory = ctx.primitives?.[primitive.name];
    if (typeof primitiveFactory !== 'function') continue;
    const result = primitiveFactory(root, primitive.params ?? {});
    if (result) primitiveHandles.push(result);
  }

  const animateLift = (amount, duration, ease) => {
    const tween = gsap.to(ornament.position, {
      y: amount,
      duration,
      ease,
      overwrite: true
    });
    animationHandles.push(tween);
  };

  root.userData.handlers.hover = () => {
    animateLift(0.15, 0.5, 'power3.out');
    const tween = gsap.to(accentEdge.material, {
      opacity: 0.42,
      duration: 0.3,
      ease: 'power2.out',
      overwrite: true
    });
    animationHandles.push(tween);
  };

  root.userData.handlers.hoverEnd = () => {
    animateLift(0, 0.5, 'power3.out');
    const tween = gsap.to(accentEdge.material, {
      opacity: 0,
      duration: 0.3,
      ease: 'power2.out',
      overwrite: true
    });
    animationHandles.push(tween);
  };

  root.userData.handlers.focus = () => {
    const tween = gsap.to(accentEdge.material, {
      opacity: 0.9,
      duration: 0.22,
      ease: 'power2.out',
      overwrite: true
    });
    animationHandles.push(tween);
  };

  root.userData.handlers.blur = () => {
    const tween = gsap.to(accentEdge.material, {
      opacity: 0,
      duration: 0.22,
      ease: 'power2.out',
      overwrite: true
    });
    animationHandles.push(tween);
  };

  root.userData.handlers.click = () => {
    const press = gsap.timeline();
    press.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power2.out'
    }).to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.42,
      ease: 'back.out(2)'
    });
    animationHandles.push(press);
    ctx.emit('hub-home.select', { node: 'ornamental-divider' });
  };

  root.userData.cleanup = () => {
    for (const handle of animationHandles) {
      if (handle?.kill) handle.kill();
    }
    for (const handle of primitiveHandles) {
      if (handle?.cleanup) handle.cleanup();
      if (handle?.timeline?.kill) handle.timeline.kill();
    }
    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();
      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];
        for (const material of materials) {
          if (material.dispose) material.dispose();
        }
      }
    });
    for (const resource of ownedResources) {
      if (resource?.dispose) resource.dispose();
    }
  };

  return root;
}

export default createNode;
